def minOperations(nums):
    # Sieve of Eratosthenes, a bit past 10^5 since the next prime after 100000 is 100003
    LIMIT = 100200
    is_prime = [True] * (LIMIT + 1)
    is_prime[0] = is_prime[1] = False
    i = 2
    while i * i <= LIMIT:
        if is_prime[i]:
            for j in range(i * i, LIMIT + 1, i):
                is_prime[j] = False
        i += 1

    ops = 0
    for idx, x in enumerate(nums):
        y = x
        if idx % 2 == 0:
            # Even index must be prime: walk up to the next prime
            while not is_prime[y]:
                y += 1
        else:
            # Odd index must be non-prime: walk up to the next non-prime
            while is_prime[y]:
                y += 1
        ops += y - x

    return ops
